import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CRFziyHp.js";const g=JSON.parse('{"title":"私信与群聊","description":"私信与群聊：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/message.md","filePath":"features/message.md","lastUpdated":1785018026000}'),l={name:"features/message.md"};function i(s,t,n,d,h,u){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="私信与群聊" tabindex="-1">私信与群聊 <a class="header-anchor" href="#私信与群聊" aria-label="Permalink to &quot;私信与群聊&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>为用户提供私聊、群聊及消息实时收发；红包、转账等增值能力依赖支付模块。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>站点 Redis 与 WebSocket 服务正常（由部署环境保障，管理员只需确认 <strong>系统监控 → 系统状态</strong> 无 Redis 断连）。</li><li>即时通讯相关功能已在授权中开通。</li><li>红包 / 转账额外需要 <a href="/features/payment">支付与提现</a> 配置完成。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="会话监管" tabindex="-1">会话监管 <a class="header-anchor" href="#会话监管" aria-label="Permalink to &quot;会话监管&quot;">​</a></h3><p>路径：<strong>用户体系 → 群聊私信</strong></p><ul><li>查看全站或按区域筛选的会话列表</li><li>进入会话详情排查违规内容（需相应权限）</li></ul><h3 id="区域级开关" tabindex="-1">区域级开关 <a class="header-anchor" href="#区域级开关" aria-label="Permalink to &quot;区域级开关&quot;">​</a></h3><p>路径：<strong>区域管理 → 区域列表</strong> → 编辑目标区域</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>私信 / 群聊开关</td><td>关闭后本区域用户无法使用普通私信与群聊（官方机器人规则见 <a href="/features/bot-notify">官方机器人</a>）</td></tr></tbody></table><h3 id="功能级开关" tabindex="-1">功能级开关 <a class="header-anchor" href="#功能级开关" aria-label="Permalink to &quot;功能级开关&quot;">​</a></h3><p>部分能力由 <strong>授权模块</strong> 控制是否在客户端展示红包、转账入口；未开通时菜单与按钮不会出现。开通后仍须：</p><ul><li><strong>系统设置 → 系统配置 → 微信支付</strong>（或支付宝）已配置</li><li>用户有足够余额或绑定支付方式</li></ul><h3 id="websocket-连接-运维侧" tabindex="-1">WebSocket 连接（运维侧） <a class="header-anchor" href="#websocket-连接-运维侧" aria-label="Permalink to &quot;WebSocket 连接（运维侧）&quot;">​</a></h3><p>若用户普遍「消息发不出、一直连接中」，请运维检查反向代理是否支持 WebSocket 升级；管理员可在 <strong>系统监控 → 在线用户</strong> 观察连接数是否异常。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置位置</th><th>作用</th></tr></thead><tbody><tr><td><strong>区域列表 → 私信开关</strong></td><td>按区域启用 / 禁用 IM</td></tr><tr><td><strong>官方机器人</strong></td><td>区域关闭私信时，可能仍保留官方通知通道</td></tr><tr><td><strong>用户配置</strong></td><td>注册登录与 IM 无直接开关，但禁言用户无法发言</td></tr></tbody></table><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>在已开启私信的区域，两测试账号互发私聊，双方实时收到。</li><li>创建群聊并拉入成员，群消息同步正常。</li><li>（可选）发起小额 <strong>聊天转账</strong> 或 <strong>群红包</strong>，支付成功后消息卡片状态更新，<strong>财务管理 → 资金交易</strong> 有记录。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>全员无法收发消息</strong></p><ul><li><strong>系统监控 → 系统状态</strong> 查看 Redis、WebSocket 是否正常。</li><li>/nginx 未配置 <code>Upgrade</code> 头会导致 H5 长连接失败，联系运维处理。</li></ul><p><strong>仅某区域不可用</strong></p><ul><li>检查 <strong>区域列表</strong> 中该区域是否关闭私信。</li><li>用户是否被拉黑或禁言。</li></ul><p><strong>红包 / 转账按钮不存在</strong></p><ul><li>确认授权已含红包 / 转账能力且 <a href="/features/payment">支付</a> 已配置。</li><li>部分客户端仅在群聊或私聊特定入口展示。</li></ul><p><strong>消息延迟</strong></p><ul><li>查看 <strong>系统监控 → 定时任务</strong> 是否积压；<strong>通知控制台 → 消息链路追踪</strong> 排查投递延迟。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/bot-notify">官方机器人</a></li><li><a href="/features/payment">支付与提现</a></li><li><a href="/features/notification">通知与推送</a></li></ul>',32)])])}const b=a(l,[["render",i]]);export{g as __pageData,b as default};
